import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.C-si7TFR.js";const _=JSON.parse('{"title":"创建、版本与排障","description":"","frontmatter":{"title":"创建、版本与排障"},"headers":[],"relativePath":"zh/guide/workflows.md","filePath":"zh/guide/workflows.md"}'),r={name:"zh/guide/workflows.md"};function o(n,a,s,h,d,c){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="创建、版本与排障" tabindex="-1">创建、版本与排障 <a class="header-anchor" href="#创建、版本与排障" aria-label="Permalink to &quot;创建、版本与排障&quot;">​</a></h1><h2 id="从明确的流程开始" tabindex="-1">从明确的流程开始 <a class="header-anchor" href="#从明确的流程开始" aria-label="Permalink to &quot;从明确的流程开始&quot;">​</a></h2><ol><li>在工作流模式选择<strong>新建</strong>，添加手动触发器。</li><li>从节点菜单选择逻辑、工具或 AI 节点，连线形成执行路径。</li><li>为每个节点配置输入和输出，保存后手动执行。</li><li>检查执行记录，再添加定时或 API 触发。</li></ol><p><a href="./../trigger_start.html">手动触发器</a>适合调试；同步／异步 API 有各自的调用和返回语义，不能随意替换。</p><h2 id="让-agent-协助创建或修改" tabindex="-1">让 Agent 协助创建或修改 <a class="header-anchor" href="#让-agent-协助创建或修改" aria-label="Permalink to &quot;让 Agent 协助创建或修改&quot;">​</a></h2><ol><li>在对话中给出明确目标、输入、处理步骤和期望输出。</li><li>如页面显示“添加流程”，先创建入口，再要求 Agent 生成流程。</li><li>检查工作流预览卡片和生成结果；需要进入画布时使用<strong>打开流程</strong>。</li><li>要求修改时，查看<strong>修改前后差异</strong>，不要只凭“已修改”的文字保存。</li><li>保存后检查版本和手动执行结果。</li></ol><p>工作流工具用于 Agent 调用已启用的 API 流程，与 Agent 协助创建／编辑流程不是同一个功能。</p><h2 id="调试与版本" tabindex="-1">调试与版本 <a class="header-anchor" href="#调试与版本" aria-label="Permalink to &quot;调试与版本&quot;">​</a></h2><ul><li>在 Agent 对话或画布中执行调试，核对失败节点、输入和错误。</li><li>在流程版本入口查看变化、比较版本；回滚前确认要恢复的目标版本和当前未保存变化。</li><li>回滚版本不是删除执行记录，也不能撤销已经对外部系统产生的副作用。</li></ul><h2 id="执行记录与-ai-诊断" tabindex="-1">执行记录与 AI 诊断 <a class="header-anchor" href="#执行记录与-ai-诊断" aria-label="Permalink to &quot;执行记录与 AI 诊断&quot;">​</a></h2><ol><li>打开目标流程的执行记录，选择失败执行。</li><li>检查节点状态、错误、重试与关联链路。</li><li>失败执行提供 AI 诊断入口时，可使用该入口辅助分析；诊断不是自动修复。</li><li>回到画布修正，另做一次手动验证。</li></ol><p>日志和诊断上下文可能包含凭证、提示词、业务数据或外部地址，分享前应脱敏。模型不可用时，诊断入口不代表能够完成诊断。</p><h2 id="安全执行" tabindex="-1">安全执行 <a class="header-anchor" href="#安全执行" aria-label="Permalink to &quot;安全执行&quot;">​</a></h2><p>外部请求、SSH、文件和脚本节点会触及实际系统。限制目标地址、目录和凭证，使用参数绑定，避免把用户输入拼接到命令或 SQL。先以无副作用数据调试，再启用无人值守触发。</p>',14)])])}const g=l(r,[["render",o]]);export{_ as __pageData,g as default};
